using System;
using System.Collections.Generic;
using System.Threading.Tasks;

// PROGRAM: Simulasi Pola Unit of Work dan Specific Repository
public interface IOrderRepository
{
    void Add(string orderId, decimal total);
}

public interface IUnitOfWork
{
    IOrderRepository Orders { get; }
    void Commit();
}

public class MemoryUnitOfWork : IUnitOfWork
{
    public class MemoryOrderRepository : IOrderRepository
    {
        public List<string> PendingInserts = new();
        public void Add(string orderId, decimal total) => PendingInserts.Add($"{orderId}: Rp {total:N0}");
    }

    public MemoryOrderRepository OrderRepo { get; } = new();
    public IOrderRepository Orders => OrderRepo;

    public void Commit()
    {
        Console.WriteLine($"[TRANSACTION COMMIT] Menyimpan {OrderRepo.PendingInserts.Count} order secara atomik.");
        foreach (var ord in OrderRepo.PendingInserts)
        {
            Console.WriteLine($"  -> Persisted: {ord}");
        }
        OrderRepo.PendingInserts.Clear();
    }
}

public class Program
{
    public static void Main()
    {
        var uow = new MemoryUnitOfWork();
        uow.Orders.Add("ORD-001", 150_000m);
        uow.Orders.Add("ORD-002", 300_000m);

        Console.WriteLine("Memanggil Unit of Work Commit...");
        uow.Commit();
    }
}

