using System;

public class TransactionCoordinator
{
    public static bool ExecuteTransactionalOperation(bool step1Success, bool step2Success)
    {
        if (step1Success && step2Success)
        {
            Console.WriteLine("[COMMIT] Transaction committed successfully");
            return true;
        }

        Console.WriteLine("[ROLLBACK] Transaction rolled back");
        return false;
    }

    public static void Main()
    {
        Console.WriteLine(ExecuteTransactionalOperation(true, true));
        Console.WriteLine(ExecuteTransactionalOperation(true, false));
    }
}
